SELECT     CONCAT(CAST(SUBSTRING(CAST(tjzq AS VARCHAR(20)), 5, 1) AS INT), '月') AS month,     ROUND(SUM(CASE         WHEN SUBSTRING(CAST(tjzq AS VARCHAR(20)), 1, 4) = #{ssnd}         THEN djsjje         ELSE 0     END) / 100000000, 2) AS bngjje,     ROUND(SUM(CASE         WHEN SUBSTRING(CAST(tjzq AS VARCHAR(20)), 1, 4) = CAST(#{ssnd} AS INT) - 1         THEN djsjje         ELSE 0     END) / 100000000, 2) AS sngjje FROM dws_bus_per_paid_qfq WHERE SUBSTRING(CAST(tjzq AS VARCHAR(20)), 1, 4) IN (#{ssnd}, CAST(#{ssnd} AS INT) - 1) GROUP BY SUBSTRING(CAST(tjzq AS VARCHAR(20)), 5, 1) ORDER BY month
